{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Provides three actions for placing selected material on new copies of its source tracks.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Duplicate to New Copy of a Track and Move to 0.00 copies the material and shifts the result so its earliest point is at 0.00.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Duplicate to New Copy of a Track copies the material at its original timeline position.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Move to New Copy of a Track moves the original material at its original timeline position.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Razor Edits take priority over selected media items. Media-item Razor Edits process only material inside their boundaries; envelope Razor Edits are ignored. Without Razor Edits, selected items are processed in full.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab New tracks keep the source track settings and use minimum height.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Prepares selected items for batch mastering.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Orders standalone tracks and folder groups from top to bottom.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Aligns selected items in the same nearest folder at one start position.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Places each following block immediately after the longest item before it.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Treats multiple selected items on one track as one continuous block.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Creates one selected region and render-matrix entry per selected track.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Renders every selected track separately through its routing and master.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Preserves multichannel sources and enables multichannel peak meters.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Renames regions and item tracks from the best available item name.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Deletes existing regions before creating the current region set.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Separates overlapping folder regions into ruler lanes.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Colors tracks with global and per-folder gradients.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Gives each region the custom color of its source track.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires REAPER 7.78 or later.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Switches any toolbar positioned at the top of the main window to the configured target toolbar, then back to the previous toolbar. Restores the window focus that was active before the script ran.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires js_ReaScriptAPI.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Adds JS: Volume Adjustment to the selected track.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Sets Adjustment to 0 dB.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Shows the Adjustment automation envelope.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Leaves the plug-in window closed.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Toggles the freeze state of every selected track.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Unfrozen track: freeze to stereo.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Frozen track: unfreeze one freeze layer.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Mixed multi-track selections are processed independently.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab The original track selection is restored afterwards.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Toggles the freeze state of every selected track.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Unfrozen track: measures the real frozen output, then freezes natively with five seconds of confirmed silence after the audible tail.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Frozen track: unfreezes one freeze layer.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Mixed multi-track selections are processed independently.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Requires the free SWS/S&M extension.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Toggles the FX window of the selected track.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Closed window: close all track FX windows, then open its FX chain.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Open window: close all track FX windows.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Supports normal tracks, the master track, and floating FX.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Classifies and orders tracks from the active preset, creates category folders, and places every unclassified track in OTHER at the end. Existing user folders are moved only as balanced atomic subtrees. Set dry_run=true in the active preset for a console-only preview.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 icanscriptsounds\par}
{\pard \ql \f0 \sa180 \li0 \fi0 A personal collection of scripts for {\field{\*\fldinst{HYPERLINK "https://www.reaper.fm/"}}{\fldrslt{\ul
REAPER
}}}
, distributed through {\field{\*\fldinst{HYPERLINK "https://reapack.com/"}}{\fldrslt{\ul
ReaPack
}}}
.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Install with ReaPack\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \f1 https://raw.githubusercontent.com/lsooxlla8/icanscriptsounds/main/index.xml\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Packages\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Items\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 New Track Copies\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b Duplicate to New Copy of a Track and Move to 0.00} \u8212- copies selected items or media-item Razor Edit material to new copies of their source tracks, then shifts the result so its earliest point is at 0.00.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b Duplicate to New Copy of a Track} \u8212- copies selected items or media-item Razor Edit material to new copies of their source tracks at the original timeline position.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b Move to New Copy of a Track} \u8212- moves selected items or media-item Razor Edit material to new copies of their source tracks at the original timeline position.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 Prepare Selected Items for Mastering\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Arranges selected items into mastering blocks, creates one colored region and Region Render Matrix entry per selected track, and configures multichannel WAV rendering through the master track. Audio, MIDI, generated-source and empty items are supported. Foldered tracks share a start position and use separate visible ruler lanes. Requires REAPER 7.78 or later.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Track Management\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 Track Organizer\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Sorts imported multitracks into a stable folder hierarchy using an editable rule library. Includes five workflow presets, direct preset actions and {\b icss_Track Organizer Rule Manager} for visual editing, ordering, previews and classification diagnostics. Unmatched tracks are placed in {\f1 OTHER} at the end.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 Freeze Toggles\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b Freeze Toggle} \u8212- toggles every selected track independently: an unfrozen track is frozen to stereo; a frozen track is unfrozen by one freeze layer.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b Smart Freeze Toggle} \u8212- toggles every selected track independently: an unfrozen track gets a measured safe post-FX tail and is then frozen to stereo; a frozen track is unfrozen by one freeze layer. The silence threshold is set 66 dB below the loudest 50 ms RMS window before the tail.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 {\b Smart Freeze Toggle} requires the {\field{\*\fldinst{HYPERLINK "https://www.sws-extension.org/"}}{\fldrslt{\ul
SWS/S&M extension
}}}
.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 FX and Automation\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 Add Volume Adjustment Automation\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Adds JS: Volume Adjustment to the selected track, sets Adjustment to 0 dB, shows its automation envelope, and leaves the plug-in window closed.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 Smart Toggle FX Window\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Toggles the FX window of the selected track:\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab closed window \u8594 ? close all track FX windows, then open its FX chain;\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab open window \u8594 ? close all track FX windows.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Toolbars\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel3 \b \fs24 Toggle Toolbar at Top\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Toggles the toolbar positioned "At top of main window":\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab any current toolbar \u8594 ? the configured target toolbar;\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab target toolbar \u8594 ? the previously active toolbar.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Set {\f1 TARGET_TOOLBAR} in the script to a toolbar number from 1 to 32. The script requires {\field{\*\fldinst{HYPERLINK "https://forum.cockos.com/showthread.php?t=212174"}}{\fldrslt{\ul
js_ReaScriptAPI
}}}
.\par}
}
